                color = row[c - 1]
                out[r][c] = color
                marks_by_col.setdefault(c, []).append((r, color))

    for c, marks in marks_by_col.items():
        marks.sort()

        # Extend the first bar's gap upward.
        first_r, first_color = marks[0]
        for r in range(first_r):
            out[r][c] = first_color

        # Between bars, use the color of the next bar's gap.
        for i in range(1, len(marks)):
            r, color = marks[i]
            prev_r = marks[i - 1][0]
            for y in range(prev_r + 1, r):
                out[y][c] = color

        # Below the last bar, continue using the vertical guide's color, if present.
        last_r = marks[-1][0]
        guide_color = next(
            (grid[r][c] for r in range(last_r + 1, h) if grid[r][c] != 0),
            marks[-1][1]
        )
        for r in range(last_r + 1, h):
            out[r][c] = guide_color

    return out
